// Photos locales : déposez simplement une image nommée <id-du-produit>.jpg (ou .png/.webp/.jpeg)
// dans src/assets/products/ — elle s'affichera automatiquement à la place de l'icône.
// Exemple : src/assets/products/fruit-banane.jpg
const LOCAL_PHOTOS = import.meta.glob('../assets/products/*.{jpg,jpeg,png,webp,JPG,JPEG,PNG,WEBP}', {
  eager: true,
  query: '?url',
  import: 'default',
}) as Record<string, string>;

const photoFor = (id: string): string | undefined => {
  const key = Object.keys(LOCAL_PHOTOS).find((k) => {
    const file = k.split('/').pop() || '';
    return file.replace(/\.[^.]+$/, '').toLowerCase() === id.toLowerCase();
  });
  return key ? LOCAL_PHOTOS[key] : undefined;
};

const STYLE: Record<string, { color: string; accentColor: string; bgGradient: string; tag: string }> = {
  fruits: { color: '#F59E0B', accentColor: '#B45309', bgGradient: 'from-amber-50 to-orange-100', tag: 'Fruit frais • Au kilo' },
  legumes: { color: '#16A34A', accentColor: '#166534', bgGradient: 'from-lime-50 to-emerald-100', tag: 'Légume frais' },
  viande: { color: '#DC2626', accentColor: '#991B1B', bgGradient: 'from-rose-50 to-red-100', tag: 'Viande fraîche • Au kilo' },
  'viandes-marinees': { color: '#EA580C', accentColor: '#9A3412', bgGradient: 'from-orange-50 to-amber-100', tag: 'Marinade maison • Prêt à cuire' },
  pepiniere: { color: '#65A30D', accentColor: '#3F6212', bgGradient: 'from-lime-50 to-green-100', tag: 'Plants de pépinière' },
};

export const CATALOG_PRODUCTS: Product[] = RAW.map((r) => {
  const s = STYLE[r.category];
  return {
    ...r,
    naturalTag: s.tag,
    imageUrl: photoFor(r.id),
    benefits: [],
    color: s.color,
    accentColor: s.accentColor,
    bgGradient: s.bgGradient,
    imageAlt: r.name + ' SENAM AGRO',
  };
});
